import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.iXqqCa-C.js";const i="/images/agent-proactive.webp",u=JSON.parse('{"title":"主动消息","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/proactive.md","filePath":"guide/agent/proactive.md","lastUpdated":1793501934000}'),o={name:"guide/agent/proactive.md"};function l(n,t,s,h,p,c){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="主动消息" tabindex="-1">主动消息 <a class="header-anchor" href="#主动消息" aria-label="Permalink to &quot;主动消息&quot;">​</a></h1><p>角色可以在你没有发消息时主动发来消息。冷落太久的话，角色可能会先来找你。</p><h2 id="前提-时间感知" tabindex="-1">前提：时间感知 <a class="header-anchor" href="#前提-时间感知" aria-label="Permalink to &quot;前提：时间感知&quot;">​</a></h2><p>主动消息依赖<strong>时间感知</strong>（把当前北京时间告诉角色，会话设置中默认开启）。如果主动消息无法开启，先到「会话」标签页确认时间感知已打开。</p><h2 id="两种方式" tabindex="-1">两种方式 <a class="header-anchor" href="#两种方式" aria-label="Permalink to &quot;两种方式&quot;">​</a></h2><ul><li><strong>随机主动</strong>：会话静默一段时间后，角色会在随机时刻主动发来消息，白天的概率高于夜间。</li><li><strong>定时主动</strong>：角色可以自主创建、调整或取消最多 5 个定时计划，比如「每天早上叫你起床」。</li></ul><h2 id="随机主动消息参数" tabindex="-1">随机主动消息参数 <a class="header-anchor" href="#随机主动消息参数" aria-label="Permalink to &quot;随机主动消息参数&quot;">​</a></h2><p>「主动消息」标签页可以调整随机主动消息的参数，「恢复默认」可还原站点默认值：</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td>最小静默时间</td><td>角色回复后至少等待多久才发送，5–1440 分钟</td></tr><tr><td>最大等待窗口</td><td>从静默结束起，在多长时间内随机选取发送时刻，30–10080 分钟</td></tr><tr><td>白天权重倍率</td><td>1–10，1 表示白天与夜间概率相同，3 表示白天概率是夜间的 3 倍</td></tr><tr><td>近期偏好系数</td><td>1–10，1 表示在窗口内均匀分布，值越大越偏向近期时间点</td></tr><tr><td>连续主动次数</td><td>你没有回复时角色最多连续发送几次，上限由站点设置</td></tr></tbody></table><h2 id="管理定时计划" tabindex="-1">管理定时计划 <a class="header-anchor" href="#管理定时计划" aria-label="Permalink to &quot;管理定时计划&quot;">​</a></h2><p>「主动消息」标签页会列出当前所有定时计划，每个计划显示：</p><ul><li>描述（角色打算做什么）</li><li>状态：执行中 / 已暂停 / 已完成 / 已取消</li><li>下次执行时间</li><li>剩余次数（一次性计划会标注「一次性」，无限重复的计划不显示）</li></ul><p>你可以随时<strong>暂停、恢复或删除</strong>任意计划；过期的一次性计划无法恢复。</p><p>计划由角色自己维护，会在对话中按你们的约定调整，调整结果体现在计划列表里。某次执行失败时，会提示「上次执行失败，本次已跳过」。</p><p><img src="'+i+'" alt="主动消息"></p>',15)])])}const g=a(o,[["render",l]]);export{u as __pageData,g as default};
